const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sacramento = ee.Geometry.Point([-121.4965, 38.5816]);
  const startDate = '2022-09-01';
  const endDate = '2022-09-30';
  const tempThresholdF = 110;

  // 2. Data Acquisition
  const collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterBounds(sacramento)
    .filterDate(startDate, endDate)
    .select('temperature_2m');

  // Check if collection is empty
  const collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log('Evidence: No images found for the specified date and location.');
    console.log('A: C1');
    return;
  }
  console.log(`Evidence: Found ${collectionSize} hourly images for September 2022.`);

  // 3. Processing: Find the maximum temperature over the time period
  const maxTempImage = collection.max();

  // 4. Calculation: Get the max temperature value at the point
  const maxTempDict = maxTempImage.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: sacramento,
    scale: 1000, // Native resolution is ~11km, 1000m is safe
    maxPixels: 1e9
  });

  const maxTempKelvin = maxTempDict.get('temperature_2m').getInfo();

  // 5. Validation & Final Answer
  if (maxTempKelvin === null || maxTempKelvin === undefined) {
    console.log('Evidence: Could not calculate maximum temperature. Result was null.');
    console.log('A: C3');
    return;
  }

  // Convert Kelvin to Fahrenheit
  const maxTempFahrenheit = ((maxTempKelvin - 273.15) * 9 / 5) + 32;

  console.log(`Evidence: Maximum 2-meter air temperature in Sacramento, Sep 2022: ${maxTempFahrenheit.toFixed(2)} °F.`);
  console.log(`Evidence: The threshold for the question is > ${tempThresholdF} °F.`);

  if (maxTempFahrenheit > tempThresholdF) {
    console.log('A: Yes');
  } else {
    console.log('A: No');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log('A: D');
});
